/**
 * Types shared with the web app. The schema types come straight from the API's OpenAPI spec
 * (src/api/v1.d.ts, generated by `npm run gen:api`), so a change in the API shows up here as a
 * type error. The app's own session endpoints return the same shapes.
 */
import type { components } from "./v1";

type S = components["schemas"];

export type Address = S["Address"];
export type Approval = S["Approval"];
export type Agent = S["Agent"];
export type Folder = "inbox" | "sent" | "drafts" | "archive" | "spam" | "trash";
export type ListFolder = Folder | "starred";

export type MessageSummary = S["MessageSummary"] & {
  /** Set when one of your agents wrote it. */
  sentByAgentId?: string | null;
};

export interface Attachment { id: string; filename: string; contentType: string; sizeBytes: number; available: boolean }

export interface Message extends MessageSummary {
  cc: Address[];
  bcc: Address[];
  replyTo: string | null;
  text: string;
  html: string | null;
  attachments: Attachment[];
}

export interface MessagePage { messages: MessageSummary[]; nextCursor: string | null }
export interface ThreadView { message: Message; thread: Message[] }

export interface MailboxOverview {
  id: string;
  address: string;
  displayName: string;
  usedBytes: number;
  quotaMb: number;
  kind?: "person" | "agent";
  folders: Partial<Record<Folder, { total: number; unread: number }>>;
}

export type Role = "owner" | "admin" | "member";

export interface Me {
  user: { id: string; email: string; name: string; emailVerified: boolean; twoFactor: boolean; platformAdmin: boolean };
  organization: { id: string; name: string; plan: string; isDemo: boolean; role: Role; timezone: string; country: string } | null;
}

export interface SendInput {
  mailboxId: string;
  to: string[];
  cc?: string[];
  subject: string;
  text: string;
  inReplyToId?: string;
}

export interface SendResult { messageId: string; status?: string; [k: string]: unknown }

// ---------------------------------------------------------------- work management

export type TaskStatus = "todo" | "doing" | "done";
export type Priority = "none" | "low" | "medium" | "high" | "urgent";
export type AssigneeId = `member:${string}` | `agent:${string}`;

export interface Assignee { id: AssigneeId; type: "member" | "agent"; name: string; email: string | null }

/** A task as GET /api/tasks returns it. */
export interface Task {
  id: string;
  ref: string;
  projectId: string | null;
  number: number;
  title: string;
  notes: string;
  statusId: string | null;
  statusName: string;
  statusColor: string | null;
  status: TaskStatus;
  assignee: { type: "member" | "agent"; id: string; name: string; email: string | null } | null;
  assigneeId: AssigneeId | null;
  priority: Priority;
  labels: string[];
  start: string | null;
  due: string | null;
  parentId: string | null;
  position: number;
  source: { threadId: string | null; messageId: string | null; from: string | null; subject: string | null } | null;
  subtasks: { total: number; done: number };
  commentCount: number;
  completedAt: string | null;
  createdBy: { type: string; id: string };
  createdAt: string;
  updatedAt: string;
  version: number;
  /** Custom field values by field id. Older servers leave it out. */
  fields?: FieldValues;
  /** R27: checklist progress for the "3/5" badge. Servers before R26 leave it out. */
  checklist?: { total: number; done: number };
}

/** R27: one checklist item inside a task (server R26, MB-85). */
export interface ChecklistItem {
  id: string;
  taskId: string;
  title: string;
  done: boolean;
  position: number;
  assignee: string | null;
  due: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface ChecklistView { taskId: string; items: ChecklistItem[]; total: number; done: number }

/** R29: an AI agent member's run on a task (server R27 agent runs, read only in the app). */
export type RunStatus = "queued" | "running" | "succeeded" | "failed" | "cancelled";
export type RunStepKind = "note" | "tool" | "comment" | "status_change";
export interface RunStep { at: string; kind: RunStepKind | string; text: string }
export interface AgentRun {
  id: string;
  taskId: string;
  task: { ref: string; title: string } | null;
  agent: { userId: string; name: string; avatarColor?: string; isAgent?: true };
  status: RunStatus | string;
  startedAt: string | null;
  finishedAt: string | null;
  durationMs: number | null;
  result: string | null;
  stepCount: number;
  /** Empty on the workspace list; filled on one run and on a task's runs. */
  steps: RunStep[];
  createdAt: string;
  updatedAt: string;
  triggerId?: string | null;
}

export interface TaskComment { id: string; taskId: string; body: string; author: { type: string; id: string; name: string | null }; createdAt: string }

export interface TaskThreadItem {
  id: string;
  mailboxId?: string;
  direction: "inbound" | "outbound";
  from: { address: string; name: string | null };
  subject: string;
  date: string;
  latestText: string;
  byAgent: boolean;
}

export interface TaskActivity { id: string; actor: { type: string; id: string; name: string | null }; verb: string; data: Record<string, unknown>; at: string }

export interface TaskDetail {
  task: Task;
  subtasks: Task[];
  comments: TaskComment[];
  thread: TaskThreadItem[];
  activity: TaskActivity[];
  docs: { id: string; title: string; updatedAt: string }[];
  contacts: { id: string; name: string | null; email: string | null }[];
}

/** One stretch of time on a task: a running or stopped timer, or a manual entry. */
export interface TimeEntry {
  id: string;
  taskId: string | null;
  task: { id: string; ref: string; title: string } | null;
  projectId: string | null;
  person: { type: "member" | "agent"; id: string; name: string };
  startedAt: string;
  endedAt: string | null;
  running: boolean;
  seconds: number;
  note: string;
  billable: boolean;
  source: "timer" | "manual";
}

export interface TimeLog { taskId: string; minutes: number; date?: string; note?: string }

/** Fields GET /api/tasks/:id adds on top of the v1 TaskDetail shape. Optional so older servers still work. */
export interface TaskExtras {
  time?: { totalSeconds: number; entries: TimeEntry[] };
  blockedBy?: Task[];
  blocking?: Task[];
  /** The project's custom field definitions, in order. */
  customFields?: CustomField[];
}
export type TaskView = TaskDetail & TaskExtras;

// ---------------------------------------------------------------- custom fields and portfolio

export type FieldType = "text" | "number" | "currency" | "date" | "select" | "multiselect" | "person" | "checkbox" | "url";
export interface FieldOption { id: string; label: string; color: string | null }
/** A custom field defined on a project. */
export interface CustomField { id: string; projectId: string; name: string; type: FieldType; options: FieldOption[]; position: number }
/** text and url: string; number and currency (AUD): number; date: "YYYY-MM-DD"; select: option id; multiselect: option ids; person: an assignee id; checkbox: boolean. */
export type FieldValue = string | number | boolean | string[];
export type FieldValues = Record<string, FieldValue | null | undefined>;

export type ProjectHealth = "on_track" | "at_risk" | "off_track";

/**
 * One row of GET /api/team/people (the same list as /api/v1/people): people (kind human), AI agent
 * members (kind agent, no email) and mail agents (type mail_agent, with their inbox address).
 */
export interface Person {
  id: string;
  type: "member" | "mail_agent";
  kind: "human" | "agent";
  userId: string | null;
  agentId: string | null;
  name: string;
  email: string | null;
  role: "owner" | "admin" | "member" | null;
  title: string | null;
  bio: string | null;
  inbox: string | null;
  joinedAt: string;
}
/** One row of GET /api/portfolio. */
export interface PortfolioProject {
  id: string;
  name: string;
  key: string;
  color: string | null;
  archived: boolean;
  owner: { id: string; name: string } | null;
  health: ProjectHealth | null;
  healthNote: string | null;
  progress: number;
  total: number;
  done: number;
  overdue: number;
  timeLoggedSeconds: number;
  nextDue: string | null;
  nextDueTask: { id: string; ref: string; title: string } | null;
}

export interface MeetingSource { type: "thread" | "task" | "contact"; id: string }

export interface Meeting {
  id: string;
  title: string;
  startsAt: string;
  durationMin: number;
  endsAt: string;
  status: string;
  source: MeetingSource | null;
  invitees: string[];
  /** The meeting page in the web app (needs a Multies sign in). */
  joinUrl: string;
  /** The guest page: works in any browser with no account. */
  guestUrl: string;
  videoEnabled: boolean;
}

export interface MeetingCreate {
  title?: string;
  startsAt?: string;
  durationMin?: number;
  source?: MeetingSource;
  invitees?: string[];
  sendInvites?: boolean;
}

export interface TaskQuery {
  status?: TaskStatus;
  threadId?: string;
  projectId?: string;
  assignee?: "me" | "none" | AssigneeId;
  q?: string;
  includeSubtasks?: boolean;
}

export interface TaskCreate {
  title: string;
  notes?: string;
  status?: TaskStatus;
  due?: string | null;
  priority?: Priority;
  labels?: string[];
  projectId?: string;
  assigneeId?: AssigneeId | null;
  parentId?: string;
  source?: { messageId?: string; threadId?: string };
}

export interface TaskPatch {
  title?: string;
  notes?: string;
  status?: TaskStatus;
  statusId?: string;
  due?: string | null;
  priority?: Priority;
  labels?: string[];
  assigneeId?: AssigneeId | null;
  position?: number;
  version?: number;
  /** Custom field values to set; null clears one. */
  fields?: Record<string, FieldValue | null>;
}

export interface Project {
  id: string;
  name: string;
  key: string;
  color: string | null;
  statuses: { id: string; name: string; category: TaskStatus; color: string | null; position: number }[];
  counts?: Record<string, number>;
}

export interface Change { seq: number; entity: string; id: string; op: string; version: number; at: string }
export interface ChangePage { changes: Change[]; cursor: number; more: boolean }

// ---------------------------------------------------------------- notifications inbox

export type NotificationCategory = "mention" | "assignment" | "comment" | "approval" | "due_soon" | "chat" | "email" | "status";
export interface AppNotification {
  id: string; type: string; category?: NotificationCategory | string;
  entityType: "task" | "message" | "chat_message" | "approval" | "goal" | string | null; entityId: string | null;
  title: string; actor?: { type: string; id: string; name: string } | null; read: boolean; createdAt: string; link?: string;
  /** R31 triage: set when the item is marked done; null or absent while it is open. */
  doneAt?: string | null;
  /** R31 triage: the item is in Later until this time. */
  snoozedUntil?: string | null;
}
export type NotificationView = "inbox" | "later" | "done";
export interface NotificationPage {
  notifications: AppNotification[]; unread: number; counts: Partial<Record<string, number>>; hasMore: boolean;
  /** R31: present when the server understood ?view= (an older server leaves it out). */
  viewCounts?: { inbox: number; later: number; done: number };
}
export interface NotificationPref { inApp: boolean; push: boolean }
export type NotificationSettings = Record<string, NotificationPref>;

// ---------------------------------------------------------------- team chat

export interface ChatMember { id: string; name: string; email: string }
export interface ChatChannel {
  id: string; kind: "channel" | "dm"; name: string; topic: string | null; private: boolean; projectId: string | null; guestAccess: boolean; archived: boolean;
  members: ChatMember[]; unread: number; mentions: number; lastMessageAt: string | null;
  lastMessage: { id: string; preview: string; authorName: string } | null; createdAt: string; joined?: boolean;
}
export interface ChatMention { type: "member" | "agent" | "channel"; id: string; name: string }
export interface ChatLink { type: "task" | "thread" | "doc"; id: string; ref: string | null; title: string; /** For a thread: its newest message, which is what the mail screen opens. */ messageId?: string }
export interface ChatAttachment { id: string; filename: string; contentType: string; size: number; /** A signed link that works without a session for at least 15 minutes. */ url?: string }
export interface ChatMessage {
  id: string; channelId: string; parentId: string | null; author: { type: "member" | "agent" | "guest"; id: string; name: string };
  body: string; mentions: ChatMention[]; links: ChatLink[]; attachments: ChatAttachment[];
  replyCount: number; lastReplyAt: string | null; editedAt: string | null; deleted: boolean; createdAt: string; updatedAt: string;
}
export interface ChatPerson { id: string; type: "member" | "agent"; name: string; email: string }
export interface ChatUnread { total: number; mentions: number; channels: Record<string, { unread: number; mentions: number }> }
export interface ChatSend { body: string; parentId?: string; attachments?: { filename: string; contentType?: string; contentBase64: string }[] }

/** What a push from the server carries: an event type and an id, nothing else. */
export type PushType = "message.received" | "approval.requested" | "task.assigned" | "task.commented" | "task.email_reply" | "task.due_soon" | "automation.status" | "automation.email"
  | "chat.mention" | "chat.dm" | "chat.reply" | "goal.updated";
export interface PushData { type: PushType | string; id: string; /** A mail thread mention: the newest message in the thread, which the thread screen opens. */ mid?: string }

// ---------------------------------------------------------------- kept in step with the API spec

/**
 * Compile-time checks against the generated spec (src/api/v1.d.ts, `npm run gen:api`): a field
 * added to or removed from the API's task shapes shows up here as a type error.
 */
type Assert<T extends true> = T;
type Same<A, B> = [A] extends [B] ? ([B] extends [A] ? true : false) : false;
type Within<A, B> = [A] extends [B] ? true : false;
export type SpecChecks = [
  // `fields` is checked apart so the app builds against specs from before and after custom fields.
  // `checklist` (R27) is on the session task rows; the v1 spec doesn't list it yet.
  Assert<Same<Exclude<keyof S["Task"], "fields" | "checklist">, Exclude<keyof Task, "fields" | "checklist">>>,
  Assert<Same<keyof S["TaskComment"], keyof TaskComment>>,
  Assert<Same<keyof NonNullable<S["TaskDetail"]>, keyof TaskDetail>>,
  Assert<Within<keyof Project, keyof S["Project"]>>,
  Assert<Within<keyof TaskCreate, keyof S["TaskCreate"] | "source">>,
  Assert<Within<Exclude<keyof TaskPatch, "fields">, keyof S["TaskPatch"]>>,
  Assert<Within<S["Task"]["status"], TaskStatus>>,
  Assert<Within<S["Task"]["priority"], Priority>>,
  Assert<Within<Pick<S["TimeEntry"], keyof TimeEntry>, TimeEntry>>,
];
